<?php
require_once __DIR__.'/../config/auth.php';require_role('owner');$pageTitle='Menu & Stok';$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_check();$action=(string)($_POST['action']??'');
 try{
  if($action==='save'){$id=(int)($_POST['id']??0);$cat=(int)($_POST['category_id']??0);$name=clean_text((string)($_POST['nama']??''),120);$desc=trim((string)($_POST['deskripsi']??''));$price=max(0,(float)($_POST['harga']??0));$stock=max(0,(int)($_POST['stok']??0));$available=isset($_POST['is_available'])?1:0;$best=isset($_POST['is_best_seller'])?1:0;if(!$cat||$name==='')throw new RuntimeException('nama menu dan kategori wajib diisi.');
    $oldPhoto='';if($id){$s=$pdo->prepare('SELECT foto FROM menus WHERE id=?');$s->execute([$id]);$oldPhoto=(string)$s->fetchColumn();if(!$oldPhoto)throw new RuntimeException('menu yang diedit tidak ditemukan.');}
    $newPhoto=safe_upload_image($_FILES['foto']??[],'menus',2097152);$photo=$newPhoto?:$oldPhoto;
    if($id){$st=$pdo->prepare('UPDATE menus SET category_id=?,nama=?,deskripsi=?,harga=?,foto=?,stok=?,is_available=?,is_best_seller=? WHERE id=?');$st->execute([$cat,$name,$desc,$price,$photo,$stock,$available,$best,$id]);$menuId=$id;$message='menu berhasil diperbarui.';log_activity('update_menu',$name);}
    else{$st=$pdo->prepare('INSERT INTO menus (category_id,nama,deskripsi,harga,foto,stok,is_available,is_best_seller) VALUES (?,?,?,?,?,?,?,?)');$st->execute([$cat,$name,$desc,$price,$photo,$stock,$available,$best]);$menuId=(int)$pdo->lastInsertId();$message='menu baru berhasil ditambahkan.';log_activity('create_menu',$name);}
    $pdo->prepare('DELETE FROM menu_options WHERE menu_id=?')->execute([$menuId]);$lines=preg_split('/\r\n|\r|\n/',trim((string)($_POST['options_text']??'')));$opt=$pdo->prepare('INSERT INTO menu_options (menu_id,nama_opsi,tipe,harga_tambahan) VALUES (?,?,?,?)');foreach($lines as $line){$line=trim($line);if($line==='')continue;$parts=array_map('trim',explode('|',$line));if(count($parts)>=2){$type=safe_substr($parts[0],0,40);$optName=safe_substr($parts[1],0,100);$extra=max(0,(float)($parts[2]??0));if($type!==''&&$optName!=='')$opt->execute([$menuId,$optName,$type,$extra]);}}
  }elseif($action==='toggle'){$id=(int)$_POST['id'];$pdo->prepare('UPDATE menus SET is_available=IF(is_available=1,0,1) WHERE id=?')->execute([$id]);log_activity('toggle_menu','Mengubah ketersediaan menu ID '.$id);$message='status ketersediaan menu diperbarui.';}
  elseif($action==='delete'){$id=(int)$_POST['id'];$pdo->prepare('DELETE FROM menus WHERE id=?')->execute([$id]);log_activity('delete_menu','Menghapus menu ID '.$id);$message='menu berhasil dihapus.';}
 }catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'gagal menyimpan. pastikan kategori tidak sedang dipakai dan data valid.';}
}
$edit=null;$optsText='';if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM menus WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();if($edit){$st=$pdo->prepare('SELECT tipe,nama_opsi,harga_tambahan FROM menu_options WHERE menu_id=? ORDER BY id');$st->execute([$edit['id']]);$optsText=implode("\n",array_map(fn($o)=>$o['tipe'].' | '.$o['nama_opsi'].' | '.$o['harga_tambahan'],$st->fetchAll()));}}
$cats=dbq('SELECT id,nama FROM categories ORDER BY urutan,nama')->fetchAll();$q=trim((string)($_GET['q']??''));$st=$pdo->prepare('SELECT m.*,c.nama kategori FROM menus m JOIN categories c ON c.id=m.category_id WHERE m.nama LIKE ? ORDER BY m.created_at DESC');$st->execute(['%'.$q.'%']);$menus=$st->fetchAll();
require __DIR__.'/../includes/admin-header.php'; ?>
<?php if($message):?><div class="flash flash-ok"><?= h($message) ?></div><?php endif;?><?php if($error):?><div class="flash flash-error"><?= h($error) ?></div><?php endif;?>
<div class="grid xl:grid-cols-[390px_1fr] gap-5 items-start"><section class="card p-5"><h2 class="font-serif text-2xl"><?= $edit?'Edit menu':'Tambah menu baru' ?></h2><p class="text-xs text-coffee/55 mt-2">foto menu boleh diunggah oleh owner. format JPG/PNG/WEBP maksimal 2 MB.</p><form method="post" enctype="multipart/form-data" class="space-y-4 mt-5"><input type="hidden" name="_csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><div><label class="field-label">Nama menu</label><input class="field" name="nama" required maxlength="120" value="<?= h($edit['nama']??'') ?>"></div><div><label class="field-label">Kategori</label><select class="field" name="category_id" required><option value="">Pilih kategori</option><?php foreach($cats as $c):?><option value="<?= (int)$c['id'] ?>" <?= (int)($edit['category_id']??0)===(int)$c['id']?'selected':'' ?>><?= h($c['nama']) ?></option><?php endforeach;?></select></div><div><label class="field-label">Deskripsi</label><textarea class="field" name="deskripsi" rows="3"><?= h($edit['deskripsi']??'') ?></textarea></div><div class="grid grid-cols-2 gap-3"><div><label class="field-label">Harga (Rp)</label><input class="field" type="number" name="harga" min="0" step="500" required value="<?= h($edit['harga']??'0') ?>"></div><div><label class="field-label">Stok</label><input class="field" type="number" name="stok" min="0" required value="<?= h($edit['stok']??'0') ?>"></div></div><div><label class="field-label">Foto menu</label><input class="field" type="file" name="foto" accept="image/jpeg,image/png,image/webp"><p class="text-xs text-coffee/50 mt-1">kosongkan saat edit jika ingin tetap memakai foto sebelumnya.</p><?php if(!empty($edit['foto'])):?><img src="<?= h(str_starts_with($edit['foto'],'http')?$edit['foto']:BASE_URL.'/'.$edit['foto']) ?>" class="w-24 h-20 object-cover rounded-xl mt-2" alt="Foto saat ini"><?php endif;?></div><div class="flex flex-wrap gap-4"><label class="text-sm flex items-center gap-2"><input type="checkbox" name="is_available" value="1" class="accent-[#8A9A5B]" <?= !isset($edit['is_available'])||(int)$edit['is_available']===1?'checked':'' ?>> Tersedia</label><label class="text-sm flex items-center gap-2"><input type="checkbox" name="is_best_seller" value="1" class="accent-[#8A9A5B]" <?= !empty($edit['is_best_seller'])?'checked':'' ?>> Best seller</label></div><div><label class="field-label">Varian &amp; topping (opsional)</label><textarea class="field font-mono text-xs" name="options_text" rows="5" placeholder="Ukuran | Regular | 0&#10;Ukuran | Large | 5000&#10;Suhu | Ice | 0&#10;Topping | Extra espresso | 6000"><?= h($optsText) ?></textarea><p class="text-xs text-coffee/50 mt-1">satu baris per pilihan dengan format: Tipe | Nama opsi | Harga tambahan. menyimpan akan mengganti daftar pilihan lama.</p></div><button class="btn btn-coffee w-full" type="submit"><?= $edit?'Simpan perubahan':'Tambah menu' ?></button><?php if($edit):?><a class="block text-center text-sm underline" href="<?= h(BASE_URL) ?>/admin/menus.php">Batal edit</a><?php endif;?></form></section>
<section class="card p-5"><div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3"><div><h2 class="font-serif text-2xl">Daftar menu</h2><p class="text-xs text-coffee/55 mt-1"><?= count($menus) ?> item ditampilkan</p></div><form class="flex gap-2" method="get"><input class="field !w-48" name="q" value="<?= h($q) ?>" placeholder="Cari menu"><button class="btn btn-light">Cari</button></form></div><div class="table-wrap mt-4"><table class="admin-table"><thead><tr><th>Menu</th><th>Kategori</th><th>Harga</th><th>Stok</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($menus as $m):?><tr><td><div class="flex items-center gap-3 min-w-[175px]"><img class="w-12 h-12 object-cover rounded-xl" src="<?= h(empty($m['foto'])?BASE_URL.'/assets/img/coffee-placeholder.svg':(str_starts_with((string)$m['foto'],'http')?$m['foto']:BASE_URL.'/'.$m['foto'])) ?>" alt=""><div><b><?= h($m['nama']) ?></b><?php if($m['is_best_seller']):?><span class="block text-[10px] text-sage">Best seller</span><?php endif;?></div></div></td><td><?= h($m['kategori']) ?></td><td><?= money($m['harga']) ?></td><td><span class="status-pill <?= (int)$m['stok']<=5?'status-orange':'' ?>"><?= (int)$m['stok'] ?></span></td><td><span class="status-pill <?= $m['is_available']?'status-green':'status-red' ?>"><?= $m['is_available']?'Tersedia':'Habis' ?></span></td><td><div class="flex flex-wrap gap-2"><a class="text-xs underline" href="?edit=<?= (int)$m['id'] ?>">Edit</a><form method="post"><input type="hidden" name="_csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?= (int)$m['id'] ?>"><button class="text-xs underline" type="submit">Toggle</button></form><form method="post" onsubmit="return confirm('Hapus menu ini?')"><input type="hidden" name="_csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$m['id'] ?>"><button class="text-xs text-red-700 underline">Hapus</button></form></div></td></tr><?php endforeach;?><?php if(!$menus):?><tr><td colspan="6">menu belum tersedia.</td></tr><?php endif;?></tbody></table></div></section></div>
